/* CRITICAL CSS - Mobile First */
body{background:#000;overflow-x:hidden}
.bp-wrap{position:relative;min-height:100vh;background:#000;overflow:hidden}
.bp-wrap *{box-sizing:border-box}

/* MOBILE OPTIMIZED GRADIENT */
.bp-bg-gradient{
  position:fixed;
  top:0;
  left:0;
  width:100%;
  height:100%;
  z-index:0;
  opacity:.3;
  background:radial-gradient(circle at 20% 30%,rgba(0,212,255,.25) 0%,transparent 50%),radial-gradient(circle at 80% 70%,rgba(241,7,163,.2) 0%,transparent 50%);
  pointer-events:none;
}

@media (min-width:769px){
  .bp-bg-gradient{
    animation:bp-bg-shift 20s ease-in-out 2s infinite;
    will-change:transform;
    transform:translateZ(0);
  }
}

@keyframes bp-bg-shift{
  0%,100%{transform:scale(1) rotate(0deg)}
  50%{transform:scale(1.1) rotate(10deg)}
}

/* Hero */
.bp-hero{
  position:relative;
  z-index:2;
  min-height:100vh;
  display:flex;
  align-items:center;
  padding:120px 16px 60px;
  background:transparent;
}

@media (min-width:769px){
  .bp-hero{
    padding:180px 80px 120px;
    opacity:0;
    animation:bp-fade-in .8s ease .2s forwards;
  }
