/* COST MODULE - URGENCY SECTION */
.bp-cost-module{position:relative;padding:180px 80px 120px;background:linear-gradient(180deg,rgba(0,0,0,0) 0%,rgba(10,0,15,.4) 100%);overflow:hidden;min-height:100vh}

.bp-cost-svg-filter{position:absolute;width:0;height:0;opacity:0;pointer-events:none}

.bp-cost-wrap{max-width:1800px;margin:0 auto;position:relative;z-index:2}

/* Header with Distortion */
.bp-cost-header{text-align:center;margin-bottom:100px;animation:bp-up .6s ease backwards}

.bp-cost-title{font-size:4.5rem;font-weight:300;line-height:1.15;color:#fff;letter-spacing:-.02em;margin:0}

.bp-cost-title-highlight{display:block;background:linear-gradient(90deg,#ff4655 0%,#ff8a00 25%,#ffd700 50%,#ff4655 100%);background-size:200% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;font-weight:400;animation:bp-flow 8s linear infinite}

/* Distortion on Scroll */
.bp-cost-title[data-distort]{transition:filter .3s ease}

.bp-cost-module.is-scrolling .bp-cost-title[data-distort]{filter:url(#bpBreakApart);animation:bp-shake .5s ease}

/* Horizontal Scroll Container */
.bp-cost-scroll-container{position:relative;overflow-x:auto;overflow-y:hidden;padding:60px 0;margin-bottom:80px;cursor:grab;-webkit-overflow-scrolling:touch;scrollbar-width:none}

.bp-cost-scroll-container::-webkit-scrollbar{display:none}

.bp-cost-scroll-container:active{cursor:grabbing}

.bp-cost-scroll-track{display:flex;gap:40px;padding:0 80px;width:max-content}

/* Cost Cards */
.bp-cost-card{flex:0 0 480px;height:auto;background:rgba(15,15,25,.6);border:1px solid rgba(255,255,255,.08);border-radius:16px;backdrop-filter:blur(20px);transition:all .4s cubic-bezier(.4,0,.2,1);position:relative;overflow:hidden}

.bp-cost-card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(255,70,85,.4),transparent);opacity:0;transition:opacity .4s ease}

.bp-cost-card:hover{transform:translateY(-12px);border-color:rgba(255,70,85,.3);box-shadow:0 30px 80px rgba(255,70,85,.15),0 0 0 1px rgba(255,70,85,.1)}

.bp-cost-card:hover::before{opacity:1}

.bp-cost-card-inner{padding:50px 40px}

/* Card Icon */
.bp-cost-card-icon{margin-bottom:30px;color:rgba(255,70,85,.6);opacity:.8}

/* Card Label */
.bp-cost-card-label{font-size:.85rem;font-weight:500;text-transform:uppercase;letter-spacing:.15em;color:rgba(255,70,85,.7);margin-bottom:20px}

/* Card Title */
.bp-cost-card-title{font-size:2rem;font-weight:400;color:#fff;margin-bottom:25px;line-height:1.3}

/* Card Copy */
.bp-cost-card-copy{font-size:1.075rem;font-weight:300;line-height:1.8;color:rgba(255,255,255,.6);margin-bottom:35px}

.bp-cost-card-copy strong{color:rgba(255,255,255,.9);font-weight:500}

/* Card Stat */
.bp-cost-card-stat{padding-top:30px;border-top:1px solid rgba(255,255,255,.08)}

.bp-cost-stat-number{font-size:3rem;font-weight:600;background:linear-gradient(135deg,#ff4655,#ff8a00);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:8px;line-height:1}

.bp-cost-stat-label{font-size:.95rem;font-weight:300;color:rgba(255,255,255,.5);letter-spacing:.05em}

/* Scroll Hint */
.bp-cost-scroll-hint{display:flex;align-items:center;gap:15px;justify-content:center;color:rgba(255,255,255,.4);font-size:1rem;font-weight:300;margin-bottom:80px;animation:bp-pulse 2s ease-in-out infinite}

.bp-cost-scroll-hint svg{opacity:.6}

/* CTA Section - MUCH BRIGHTER */
.bp-cost-cta-section{text-align:center;padding:80px 40px;background:linear-gradient(135deg,rgba(255,70,85,.15),rgba(255,138,0,.15));border-radius:20px;border:1px solid rgba(255,70,85,.3);backdrop-filter:blur(10px)}

.bp-cost-cta-text{font-size:1.75rem;font-weight:300;color:rgba(255,255,255,.95);margin-bottom:40px;line-height:1.5}

/* BRIGHT GLOWING CTA BUTTON */
.bp-cost-cta-btn{display:inline-flex;align-items:center;gap:15px;font-size:1.25rem;font-weight:600;color:#fff;text-decoration:none;padding:22px 50px;border-radius:10px;background:linear-gradient(135deg,#ff4655,#ff8a00);border:none;transition:all .4s ease;letter-spacing:.02em;position:relative;overflow:hidden;box-shadow:0 10px 40px rgba(255,70,85,.5),0 0 20px rgba(255,138,0,.3),0 0 0 1px rgba(255,255,255,.1) inset}

.bp-cost-cta-btn::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,#ff8a00,#ffd700);opacity:0;transition:opacity .4s ease}

.bp-cost-cta-btn::after{content:'';position:absolute;top:-50%;left:-50%;width:200%;height:200%;background:linear-gradient(45deg,transparent,rgba(255,255,255,.2),transparent);transform:rotate(45deg);transition:all .6s ease}

.bp-cost-cta-btn svg{transition:transform .4s ease;position:relative;z-index:2}

.bp-cost-cta-btn span{position:relative;z-index:2}

.bp-cost-cta-btn:hover{gap:22px;transform:translateY(-5px) scale(1.02);box-shadow:0 25px 70px rgba(255,70,85,.7),0 0 40px rgba(255,138,0,.5),0 0 60px rgba(255,70,85,.3),0 0 0 2px rgba(255,255,255,.2) inset}

.bp-cost-cta-btn:hover::before{opacity:1}

.bp-cost-cta-btn:hover::after{left:100%}

.bp-cost-cta-btn:hover svg{transform:translateX(5px)}

/* Pulsing Glow Animation */
@keyframes bp-cta-glow{
  0%,100%{box-shadow:0 10px 40px rgba(255,70,85,.5),0 0 20px rgba(255,138,0,.3),0 0 0 1px rgba(255,255,255,.1) inset}
  50%{box-shadow:0 15px 50px rgba(255,70,85,.7),0 0 30px rgba(255,138,0,.5),0 0 40px rgba(255,70,85,.3),0 0 0 1px rgba(255,255,255,.15) inset}
}

.bp-cost-cta-btn{animation:bp-cta-glow 3s ease-in-out infinite}

/* Animations */
@keyframes bp-shake{
  0%,100%{transform:translateX(0)}
  25%{transform:translateX(-5px)}
  75%{transform:translateX(5px)}
}

@keyframes bp-pulse{
  0%,100%{opacity:.4;transform:translateX(0)}
  50%{opacity:.7;transform:translateX(10px)}
}

@keyframes bp-up{
  from{opacity:0;transform:translateY(40px)}
  to{opacity:1;transform:translateY(0)}
}

@keyframes bp-flow{
  0%{background-position:0% 50%}
  50%{background-position:100% 50%}
  100%{background-position:0% 50%}
}

