  top:15%!important;
  left:5%!important;
  animation-delay:0s!important;
}

.bp-orb-pink{
  background:radial-gradient(circle,rgba(241,7,163,1),transparent 70%)!important;
  bottom:15%!important;
  right:5%!important;
  animation-delay:-10s!important;
}

.bp-contact-wrap{
  max-width:1600px!important;
  margin:0 auto!important;
  position:relative!important;
  z-index:2!important;
  width:100%!important;
}

/* Header Section */
.bp-contact-header{
  text-align:center!important;
  max-width:1100px!important;
  margin:0 auto 80px!important;
  animation:bp-fade-in 1s ease backwards!important;
}

.bp-contact-eyebrow{
  font-size:1rem!important;
  font-weight:600!important;
  text-transform:uppercase!important;
  letter-spacing:.25em!important;
  background:linear-gradient(90deg,#00d4ff,#f107a3)!important;
  -webkit-background-clip:text!important;
  -webkit-text-fill-color:transparent!important;
  background-clip:text!important;
  margin-bottom:25px!important;
}

.bp-contact-title{
  font-size:3.5rem!important;
  font-weight:700!important;
  color:#fff!important;
  margin:0 0 35px!important;
  line-height:1.15!important;
  letter-spacing:-.02em!important;
}

.bp-contact-intro{
  font-size:1.2rem!important;
  font-weight:300!important;
  line-height:1.85!important;
  color:rgba(255,255,255,.8)!important;
  margin:0 0 20px!important;
}

.bp-contact-intro-2{
  font-size:1.15rem!important;
  font-weight:300!important;
  line-height:1.8!important;
  color:rgba(255,255,255,.7)!important;
  margin:0!important;
}

/* Trust Bar - ICON BASED */
.bp-trust-bar{
  display:grid!important;
  grid-template-columns:repeat(4,1fr)!important;
  gap:25px!important;
  margin-bottom:100px!important;
  animation:bp-fade-up .8s ease backwards .2s!important;
}

.bp-trust-item{
  text-align:center!important;
  padding:30px 20px!important;
  background:rgba(20,25,40,.5)!important;
  border:1px solid rgba(255,255,255,.08)!important;
  border-radius:18px!important;
  backdrop-filter:blur(20px)!important;
  transition:all .4s ease!important;
  position:relative!important;
  overflow:hidden!important;
}

.bp-trust-item::before{
  content:''!important;
  position:absolute!important;
  inset:0!important;
  background:linear-gradient(135deg,rgba(0,212,255,.05),rgba(241,7,163,.05))!important;
  opacity:0!important;
  transition:opacity .4s ease!important;
}

.bp-trust-item:hover::before{opacity:1!important}

.bp-trust-item:hover{
  transform:translateY(-5px)!important;
  border-color:rgba(0,212,255,.25)!important;
  box-shadow:0 20px 60px rgba(0,212,255,.2)!important;
}

.bp-trust-icon{
  width:48px!important;
  height:48px!important;
  margin:0 auto 18px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  color:rgba(0,212,255,.9)!important;
  position:relative!important;
  z-index:1!important;
}

.bp-trust-number{
  font-size:2.2rem!important;
  font-weight:700!important;
  background:linear-gradient(135deg,#00d4ff,#f107a3)!important;
  -webkit-background-clip:text!important;
  -webkit-text-fill-color:transparent!important;
  background-clip:text!important;
  margin-bottom:8px!important;
  line-height:1!important;
  position:relative!important;
  z-index:1!important;
}

.bp-trust-label{
  font-size:.9rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.7)!important;
  line-height:1.4!important;
  position:relative!important;
  z-index:1!important;
}

/* Contact Grid */
.bp-contact-grid{
  display:grid!important;
  grid-template-columns:2fr 1fr!important;
  gap:40px!important;
  margin-bottom:80px!important;
  animation:bp-fade-up .8s ease backwards .4s!important;
}

/* Form Container - ELEGANT SPLIT WITH WIDER LEFT */
.bp-form-container{
  display:grid!important;
  grid-template-columns:400px 1fr!important;
  background:linear-gradient(135deg,rgba(20,25,40,.75),rgba(15,20,35,.8))!important;
  border:1px solid rgba(255,255,255,.12)!important;
  border-radius:24px!important;
  overflow:hidden!important;
  backdrop-filter:blur(40px)!important;
  box-shadow:0 40px 100px rgba(0,0,0,.4)!important;
}

/* Form Left - Decorative Side */
.bp-form-left{
  padding:50px 45px!important;
  background:linear-gradient(180deg,rgba(0,212,255,.08) 0%,rgba(241,7,163,.08) 100%)!important;
  border-right:1px solid rgba(255,255,255,.08)!important;
  position:relative!important;
  overflow:hidden!important;
}

.bp-form-decorator{
  position:absolute!important;
  top:30px!important;
  right:30px!important;
  width:100px!important;
  height:100px!important;
  opacity:.15!important;
}

.bp-decorator-circle{
  position:absolute!important;
  border:2px solid rgba(0,212,255,.6)!important;
  border-radius:50%!important;
  animation:bp-pulse-ring 3s ease-in-out infinite!important;
}

.bp-circle-1{
  width:60px!important;
  height:60px!important;
  top:0!important;
  left:0!important;
}

.bp-circle-2{
  width:40px!important;
  height:40px!important;
  top:10px!important;
  left:10px!important;
  animation-delay:1s!important;
}

.bp-decorator-line{
  position:absolute!important;
  width:2px!important;
  height:80px!important;
  background:linear-gradient(180deg,rgba(0,212,255,.4),transparent)!important;
  top:60px!important;
  left:30px!important;
  animation:bp-line-grow 2s ease-in-out infinite!important;
}

.bp-form-headline{
  font-size:2.5rem!important;
  font-weight:700!important;
  color:#fff!important;
  line-height:1.3!important;
  margin:0 0 20px!important;
  letter-spacing:-.02em!important;
}

.bp-form-subline{
  font-size:1.05rem!important;
  font-weight:300!important;
  color:rgba(255,255,255,.7)!important;
  line-height:1.7!important;
  margin:0 0 40px!important;
}

.bp-form-features{
  display:flex!important;
  flex-direction:column!important;
  gap:15px!important;
}

.bp-feature-item{
  display:flex!important;
  align-items:center!important;
  gap:12px!important;
  color:rgba(255,255,255,.85)!important;
  font-size:.95rem!important;
  font-weight:400!important;
}

.bp-feature-item svg{
  color:rgba(0,245,160,1)!important;
  flex-shrink:0!important;
}

/* Form Right - Actual Form */
.bp-form-right{
  padding:50px 45px!important;
}

.bp-form-wrapper{
  position:relative!important;
  width:100%!important;
}

/* Info Sidebar */
.bp-info-sidebar{
  display:flex!important;
  flex-direction:column!important;
  gap:25px!important;
}

.bp-info-card{
  display:flex!important;
  gap:18px!important;
  padding:28px!important;
  background:rgba(20,25,40,.5)!important;
  border:1px solid rgba(255,255,255,.08)!important;
  border-radius:18px!important;
  backdrop-filter:blur(20px)!important;
  transition:all .4s ease!important;
}

.bp-info-card:hover{
  border-color:rgba(0,212,255,.25)!important;
  transform:translateX(5px)!important;
  box-shadow:0 15px 40px rgba(0,212,255,.15)!important;
  background:rgba(20,25,40,.7)!important;
}

.bp-info-icon{
  width:44px!important;
  height:44px!important;
  border-radius:10px!important;
  background:linear-gradient(135deg,rgba(0,212,255,.18),rgba(241,7,163,.18))!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  color:rgba(0,212,255,1)!important;
  flex-shrink:0!important;
}

.bp-info-content{flex:1!important}

.bp-info-label{
  font-size:.8rem!important;
  font-weight:600!important;
  text-transform:uppercase!important;
  letter-spacing:.08em!important;
  color:rgba(255,255,255,.5)!important;
  margin-bottom:8px!important;
}

.bp-info-text{
  font-size:1rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.9)!important;
  line-height:1.6!important;
}

.bp-phone-link{
  color:rgba(255,255,255,.9)!important;
  text-decoration:none!important;
  transition:all .3s ease!important;
  display:inline-block!important;
}

.bp-phone-link:hover{
  color:rgba(0,212,255,1)!important;
  transform:translateX(3px)!important;
}

.bp-info-highlight{
  display:flex!important;
  align-items:flex-start!important;
  gap:15px!important;
  padding:25px!important;
  background:linear-gradient(135deg,rgba(0,245,160,.08),rgba(0,212,255,.08))!important;
  border:1px solid rgba(0,245,160,.2)!important;
  border-radius:16px!important;
}

.bp-info-highlight svg{
  color:rgba(0,245,160,1)!important;
  flex-shrink:0!important;
  margin-top:2px!important;
}

.bp-highlight-title{
  font-size:.95rem!important;
  font-weight:600!important;
  color:rgba(255,255,255,.95)!important;
  margin-bottom:4px!important;
}

.bp-highlight-text{
  font-size:.85rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.7)!important;
  line-height:1.5!important;
}

/* Footer Copy */
.bp-contact-footer{
  text-align:center!important;
  padding:60px 40px!important;
  background:linear-gradient(135deg,rgba(0,212,255,.04),rgba(241,7,163,.04))!important;
  border-radius:24px!important;
  border:1px solid rgba(255,255,255,.06)!important;
  backdrop-filter:blur(20px)!important;
}

.bp-footer-copy{
  font-size:1.15rem!important;
  font-weight:300!important;
  color:rgba(255,255,255,.75)!important;
  margin:0 0 20px!important;
  line-height:1.7!important;
}

.bp-footer-keywords{
  font-size:.9rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.45)!important;
  line-height:1.6!important;
}

.bp-footer-keywords span{
  display:inline-block!important;
  margin:0 8px!important;
}

/* ===== FLUENT FORMS - MAXIMUM NUCLEAR OVERRIDE ===== */

/* Complete Reset */
.bp-form-wrapper,
.bp-form-wrapper *,
.bp-form-wrapper *::before,
.bp-form-wrapper *::after{
  box-sizing:border-box!important;
}

.bp-form-wrapper .fluentform,
.bp-form-wrapper .ff-el-form-control,
.bp-form-wrapper .ff_form_wrap,
.bp-form-wrapper .ff-el-group,
.bp-form-wrapper .fluent_form_wrapper,
.bp-form-wrapper form,
.bp-form-wrapper .ff-el-input--content{
  all:unset!important;
  display:block!important;
  width:100%!important;
  background:none!important;
  border:none!important;
  box-shadow:none!important;
  padding:0!important;
  margin:0!important;
  font-family:inherit!important;
}

/* Label */
.bp-form-wrapper label,
.bp-form-wrapper .ff-el-input--label label,
.bp-form-wrapper .ff-el-input--label{
  all:unset!important;
  display:block!important;
  font-size:.8rem!important;
  font-weight:600!important;
  color:rgba(255,255,255,.6)!important;
  margin:0 0 10px 0!important;
  font-family:inherit!important;
  letter-spacing:.06em!important;
  text-transform:uppercase!important;
}

/* Input Fields - SOFT ELEGANT */
.bp-form-wrapper input[type="text"],
.bp-form-wrapper input[type="email"],
.bp-form-wrapper input[type="tel"],
.bp-form-wrapper input[type="number"],
.bp-form-wrapper input[type="url"],
.bp-form-wrapper .ff-el-form-control input{
  all:unset!important;
  display:block!important;
  width:100%!important;
  padding:14px 18px!important;
  font-size:1rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.95)!important;
  background:rgba(255,255,255,.03)!important;
  border:1px solid rgba(255,255,255,.1)!important;
  border-radius:10px!important;
  outline:none!important;
  transition:all .3s ease!important;
  box-shadow:none!important;
  font-family:inherit!important;
  -webkit-appearance:none!important;
  -moz-appearance:none!important;
  appearance:none!important;
  line-height:1.5!important;
  box-sizing:border-box!important;
}

.bp-form-wrapper input:focus{
  background:rgba(255,255,255,.05)!important;
  border-color:rgba(0,212,255,.5)!important;
  box-shadow:0 0 0 3px rgba(0,212,255,.08)!important;
}

/* TWO COLUMN GRID FOR FIRST/LAST NAME */
.bp-form-wrapper .ff-el-group:has(input[name*="first" i]),
.bp-form-wrapper .ff-el-group:has(input[name*="last" i]){
  width:calc(50% - 10px)!important;
  display:inline-block!important;
  vertical-align:top!important;
}

.bp-form-wrapper .ff-el-group:has(input[name*="first" i]){
  margin-right:20px!important;
}

/* Textarea */
.bp-form-wrapper textarea,
.bp-form-wrapper .ff-el-form-control textarea{
  all:unset!important;
  display:block!important;
  width:100%!important;
  min-height:110px!important;
  padding:14px 18px!important;
  font-size:1rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.95)!important;
  background:rgba(255,255,255,.03)!important;
  border:1px solid rgba(255,255,255,.1)!important;
  border-radius:10px!important;
  outline:none!important;
  transition:all .3s ease!important;
  resize:vertical!important;
  box-shadow:none!important;
  font-family:inherit!important;
  -webkit-appearance:none!important;
  -moz-appearance:none!important;
  appearance:none!important;
  line-height:1.6!important;
  box-sizing:border-box!important;
}

.bp-form-wrapper textarea:focus{
  background:rgba(255,255,255,.05)!important;
  border-color:rgba(0,212,255,.5)!important;
  box-shadow:0 0 0 3px rgba(0,212,255,.08)!important;
}

/* SELECT */
.bp-form-wrapper select,
.bp-form-wrapper .ff-el-form-control select{
  all:unset!important;
  display:block!important;
  width:100%!important;
  padding:14px 40px 14px 18px!important;
  font-size:1rem!important;
  font-weight:400!important;
  color:rgba(255,255,255,.95)!important;
  background:rgba(255,255,255,.03)!important;
  border:1px solid rgba(255,255,255,.1)!important;
  border-radius:10px!important;
  outline:none!important;
  transition:all .3s ease!important;
  cursor:pointer!important;
  box-shadow:none!important;
  font-family:inherit!important;
  -webkit-appearance:none!important;
  -moz-appearance:none!important;
  appearance:none!important;
  background-image:url('data:image/svg+xml;charset=UTF-8,%3csvg width="12" height="8" viewBox="0 0 12 8" fill="none" xmlns="http://www.w3.org/2000/svg"%3e%3cpath d="M1 1L6 6L11 1" stroke="%2300d4ff" stroke-width="2" stroke-linecap="round"/%3e%3c/svg%3e')!important;
  background-position:right 16px center!important;
  background-size:12px 8px!important;
  background-repeat:no-repeat!important;
  line-height:1.5!important;
  box-sizing:border-box!important;
}

.bp-form-wrapper select:hover{
  border-color:rgba(255,255,255,.18)!important;
}

.bp-form-wrapper select:focus{
  background:rgba(255,255,255,.05)!important;
  border-color:rgba(0,212,255,.5)!important;
  box-shadow:0 0 0 3px rgba(0,212,255,.08)!important;
}

.bp-form-wrapper select option{
  all:unset!important;
  background:rgba(15,20,35,.98)!important;
  color:rgba(255,255,255,.95)!important;
  padding:12px 16px!important;
  font-size:1rem!important;
  display:block!important;
}

/* Radio & Checkbox */
.bp-form-wrapper input[type="radio"],
.bp-form-wrapper input[type="checkbox"]{
  all:unset!important;
  width:20px!important;
  height:20px!important;
  border:2px solid rgba(255,255,255,.2)!important;
  background:rgba(255,255,255,.02)!important;
  cursor:pointer!important;
  display:inline-block!important;
  position:relative!important;
  transition:all .3s ease!important;
  flex-shrink:0!important;
  vertical-align:middle!important;
}

.bp-form-wrapper input[type="radio"]{border-radius:50%!important}
.bp-form-wrapper input[type="checkbox"]{border-radius:5px!important}

.bp-form-wrapper input[type="radio"]:checked,
.bp-form-wrapper input[type="checkbox"]:checked{
  border-color:rgba(0,212,255,.8)!important;
  background:rgba(0,212,255,.15)!important;
}

.bp-form-wrapper input[type="radio"]:checked::after{
  content:''!important;
  position:absolute!important;
  top:50%!important;
  left:50%!important;
  width:8px!important;
  height:8px!important;
  background:rgba(0,212,255,1)!important;
  border-radius:50%!important;
  transform:translate(-50%,-50%)!important;
}

.bp-form-wrapper input[type="checkbox"]:checked::after{
  content:'✓'!important;
  position:absolute!important;
  top:50%!important;
  left:50%!important;
  color:rgba(0,212,255,1)!important;
  font-size:13px!important;
  font-weight:700!important;
  transform:translate(-50%,-50%)!important;
  line-height:1!important;
}

/* File Upload */
.bp-form-wrapper input[type="file"]{
  all:unset!important;
  display:block!important;
  width:100%!important;
  padding:14px 18px!important;
  font-size:.95rem!important;
  color:rgba(255,255,255,.7)!important;
  background:rgba(255,255,255,.02)!important;
  border:1px dashed rgba(255,255,255,.15)!important;
  border-radius:10px!important;
  cursor:pointer!important;
  transition:all .3s ease!important;
  box-sizing:border-box!important;
}

.bp-form-wrapper input[type="file"]:hover{
  border-color:rgba(0,212,255,.3)!important;
  color:rgba(255,255,255,.95)!important;
}

/* SUBMIT BUTTON - ABSOLUTE MAXIMUM NUCLEAR OVERRIDE */
.bp-form-wrapper button[type="submit"],
.bp-form-wrapper .ff-btn-submit,
.bp-form-wrapper .wpf-submit-container button,
.bp-form-wrapper input[type="submit"],
.bp-form-wrapper button.ff-btn,
.bp-form-wrapper .ff-btn-submit.ff-btn,
.bp-form-wrapper .ff_submit_btn_wrapper button,
.bp-form-wrapper .ff_submit_btn_wrapper .ff-btn,
.bp-form-wrapper .fluentform button[type="submit"],
.bp-form-wrapper .fluentform .ff-btn-submit,
.bp-form-wrapper form button[type="submit"],
.bp-form-wrapper button[type="submit"].ff-btn,
.bp-form-wrapper .ff-btn[type="submit"]{
  all:unset!important;
  display:block!important;
  width:100%!important;
  padding:18px 40px!important;
  font-size:1.1rem!important;
  font-weight:600!important;
  color:#ffffff!important;
  text-align:center!important;
  background:linear-gradient(135deg,#00d4ff 0%,#f107a3 100%)!important;
  border:none!important;
  border-radius:12px!important;
  cursor:pointer!important;
  transition:all .3s ease!important;
  text-transform:none!important;
  letter-spacing:.02em!important;
  box-shadow:0 15px 40px rgba(0,212,255,.25)!important;
  margin:35px 0 0 0!important;
  font-family:inherit!important;
  -webkit-appearance:none!important;
  -moz-appearance:none!important;
  appearance:none!important;
  line-height:1.4!important;
  position:relative!important;
  overflow:hidden!important;
  text-decoration:none!important;
  background-color:transparent!important;
  background-image:linear-gradient(135deg,#00d4ff 0%,#f107a3 100%)!important;
  box-sizing:border-box!important;
}

/* HOVER STATE - NUCLEAR OVERRIDE */
.bp-form-wrapper button[type="submit"]:hover,
.bp-form-wrapper .ff-btn-submit:hover,
.bp-form-wrapper input[type="submit"]:hover,
.bp-form-wrapper button.ff-btn:hover,
.bp-form-wrapper .fluentform button[type="submit"]:hover,
.bp-form-wrapper button[type="submit"]:hover.ff-btn,
.bp-form-wrapper .ff-btn[type="submit"]:hover{
  background:linear-gradient(135deg,#00b8e6 0%,#d90790 100%)!important;
  background-color:transparent!important;
  background-image:linear-gradient(135deg,#00b8e6 0%,#d90790 100%)!important;
  transform:translateY(-3px)!important;
  box-shadow:0 25px 60px rgba(0,212,255,.4)!important;
  color:#ffffff!important;
  border:none!important;
  opacity:1!important;
}

/* ACTIVE STATE */
.bp-form-wrapper button[type="submit"]:active,
.bp-form-wrapper .ff-btn-submit:active{
  transform:translateY(-1px)!important;
  box-shadow:0 15px 40px rgba(0,212,255,.3)!important;
}

/* Remove Pseudo Elements */
.bp-form-wrapper button[type="submit"]::before,
.bp-form-wrapper button[type="submit"]::after,
.bp-form-wrapper .ff-btn-submit::before,
.bp-form-wrapper .ff-btn-submit::after{
  display:none!important;
  content:none!important;
  background:none!important;
}

/* Placeholder */
.bp-form-wrapper input::placeholder,
.bp-form-wrapper textarea::placeholder{
  color:rgba(255,255,255,.3)!important;
  opacity:1!important;
}

/* Form Field Spacing */
.bp-form-wrapper .ff-el-group,
.bp-form-wrapper .ff-el-input--content{
  all:unset!important;
  display:block!important;
  margin:0 0 24px 0!important;
  width:100%!important;
}

/* Error & Success */
.bp-form-wrapper .error,
.bp-form-wrapper .text-danger{
  color:rgba(255,100,100,1)!important;
  font-size:.8rem!important;
  margin:8px 0 0 0!important;
}

.bp-form-wrapper .ff-message-success{
  background:rgba(0,245,160,.1)!important;
  border:1px solid rgba(0,245,160,.3)!important;
  color:rgba(255,255,255,.95)!important;
  padding:18px!important;
  border-radius:10px!important;
  margin:20px 0!important;
}

/* Required */
.bp-form-wrapper .ff_required_field{
  color:rgba(241,7,163,1)!important;
}

/* Animations */
@keyframes bp-orb-float{
  0%,100%{transform:translate(0,0)}
  50%{transform:translate(30px,-30px)}
}

@keyframes bp-pulse-ring{
  0%,100%{transform:scale(1);opacity:.3}
  50%{transform:scale(1.1);opacity:.6}
}

@keyframes bp-line-grow{
  0%,100%{height:60px;opacity:.3}
  50%{height:90px;opacity:.6}
}

@keyframes bp-fade-in{
  from{opacity:0;transform:translateY(40px)}
  to{opacity:1;transform:translateY(0)}
}

@keyframes bp-fade-up{
  from{opacity:0;transform:translateY(50px)}
  to{opacity:1;transform:translateY(0)}
}

/* ========== RESPONSIVE BREAKPOINTS ========== */

/* Desktop Large (1400px and below) */
@media (max-width:1400px){
  .bp-form-container{grid-template-columns:360px 1fr!important}
  .bp-form-left{padding:45px 40px!important}
  .bp-form-headline{font-size:2.2rem!important}
}

/* Tablet Landscape (1200px and below) */
@media (max-width:1200px){
  .bp-contact-module{padding:150px 60px 120px!important}
  .bp-contact-title{font-size:3rem!important}
  .bp-trust-bar{grid-template-columns:repeat(2,1fr)!important}
  .bp-contact-grid{grid-template-columns:1fr!important;gap:40px!important}
  .bp-form-container{grid-template-columns:1fr!important}
  .bp-form-left{border-right:none!important;border-bottom:1px solid rgba(255,255,255,.08)!important}
  .bp-info-sidebar{grid-template-columns:repeat(2,1fr)!important;display:grid!important;gap:20px!important}
}

/* Tablet Portrait (900px and below) */
@media (max-width:900px){
  .bp-contact-module{padding:120px 40px 100px!important}
  .bp-contact-title{font-size:2.5rem!important}
  .bp-contact-intro{font-size:1.1rem!important}
  .bp-contact-intro-2{font-size:1.05rem!important}
  .bp-trust-bar{gap:20px!important}
  .bp-form-left,.bp-form-right{padding:40px 30px!important}
  .bp-info-sidebar{grid-template-columns:1fr!important}
  .bp-form-wrapper .ff-el-group:has(input[name*="first" i]),
  .bp-form-wrapper .ff-el-group:has(input[name*="last" i]){
    width:100%!important;
    display:block!important;
  }
  .bp-form-wrapper .ff-el-group:has(input[name*="first" i]){
    margin-right:0!important;
  }
}

/* Mobile Landscape (768px and below) */
@media (max-width:768px){
  .bp-contact-module{padding:100px 30px 80px!important}
  .bp-contact-title{font-size:2.2rem!important}
