  .bp-info-card{padding:22px!important;gap:15px!important}
  .bp-info-icon{width:40px!important;height:40px!important}
  .bp-info-icon svg{width:24px!important;height:24px!important}
  .bp-info-label{font-size:.75rem!important}
  .bp-info-text{font-size:.95rem!important}
  .bp-info-highlight{padding:20px!important;gap:12px!important}
  .bp-info-highlight svg{width:20px!important;height:20px!important}
  .bp-highlight-title{font-size:.9rem!important}
  .bp-highlight-text{font-size:.8rem!important}
  .bp-contact-footer{padding:45px 25px!important;border-radius:18px!important}
