/* Extra Small Mobile (400px and below) */
@media (max-width:400px){
  .bp-contact-module{padding:70px 16px 60px!important}
  .bp-contact-title{font-size:1.7rem!important}
  .bp-contact-intro{font-size:.95rem!important}
